class Solution {
public:
    int getMinSwaps(string num, int k) {
        int n = num.size();
        string target = num;
        for (int i = 0; i < k; i++) {
            nextPermutation(target);
        }

        // For each digit 0-9, store positions in num (FIFO order)
        vector<queue<int>> digitPos(10);
        for (int i = 0; i < n; i++) {
            digitPos[num[i] - '0'].push(i);
        }

        // Build position-mapping array
        vector<int> arr(n);
        for (int i = 0; i < n; i++) {
            int d = target[i] - '0';
            arr[i] = digitPos[d].front();
            digitPos[d].pop();
        }

        // Count inversions using Fenwick tree (1-indexed)
        vector<int> bit(n + 1, 0);
        long long inversions = 0;
        for (int i = n - 1; i >= 0; i--) {
            int val = arr[i] + 1;  // shift to 1-indexed
            // Query: count of already-seen values strictly less than arr[i]
            int cnt = 0;
            for (int idx = val - 1; idx > 0; idx -= idx & (-idx))
                cnt += bit[idx];
            inversions += cnt;
            // Update: insert current value
            for (int idx = val; idx <= n; idx += idx & (-idx))
                bit[idx]++;
        }

        return (int)inversions;
    }

private:
    void nextPermutation(string& s) {
        int n = s.size();
        int i = n - 2;
        while (i >= 0 && s[i] >= s[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (s[j] <= s[i]) j--;
            swap(s[i], s[j]);
        }
        reverse(s.begin() + i + 1, s.end());
    }
};
